def jsonpath_eval(expr: str, data: dict | list) -> list:
    tokens = expr.strip('$').strip('.').split('.')
    current = [data]
    for tok in tokens:
        if not tok: continue
        nxt = []
        for item in current:
            if tok == '*':
                if isinstance(item, dict): nxt.extend(item.values())
                elif isinstance(item, list): nxt.extend(item)
            elif isinstance(item, dict) and tok in item:
                nxt.append(item[tok])
        current = nxt
    return current

