import unittest
from jsonpath.eval import jsonpath_eval

class TestJSONPath(unittest.TestCase):
    def test_eval(self):
        d = {'store': {'book': [{'price': 10}, {'price': 20}]}}
        self.assertEqual(jsonpath_eval('$.store.book', d), [[{'price': 10}, {'price': 20}]])

if __name__ == '__main__': unittest.main()
